#!/usr/bin/env python3
"""Original MIT timed analog handshake guest. ST-169 §3.4 table3.37/STN-43.

All direction/control writes, TL polling and result-byte stores execute as SH-2.
No SDK, external firmware or host mailbox writes. Adjacent LICENSE.
"""
import argparse
import hashlib
import importlib.util
from pathlib import Path
import struct
HERE=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('assembler',HERE.parents[1]/'homebrew/star-collector/build.py')
assembler=importlib.util.module_from_spec(spec);spec.loader.exec_module(assembler)

def byte(address,value):
    return f'load {address:#x},r1\nmov #{value},r0\nmov.b r0,@r1\n'

def build():
    source='; Original MIT timed 3D-pad/analog-joystick handshake guest.\n'
    for at,value in [(0x100079,0x60),(0x10007B,0x60),(0x10007D,3)]: source+=byte(at,value)
    for port,count in [(0,16),(1,14)]:
        source+=f'load {0x100075+port*2:#x},r1\nload {0x0600B000+port*32:#x},r8\n'
        source+='mov #96,r0\nmov.b r0,@r1\nmov #32,r0\nmov.b r0,@r1\n'
        # Wait for initial TH acquisition response before the first TR transition.
        source+=f'mov #16,r2\nsettle{port}:\ndt r2\nbf settle{port}\n'
        for i in range(count):
            control=0x20 if i%2 else 0
            source+=f'mov #{control},r0\nmov.b r0,@r1\nwait{port}_{i}:\nmov.b @r1,r0\ntst #16,r0\n'
            source+=f'{"bt" if i%2 else "bf"} wait{port}_{i}\n'
            source+='mov.b r0,@r8\nadd #1,r8\n'
        source+='mov #96,r0\nmov.b r0,@r1\n'
    source+='load 0x0600B040,r1\nload 0x600D,r0\nmov.l r0,@r1\npark:\nsleep\nbra park\nnop\n'
    code=assembler.assemble(source,base=0x200)
    rom=bytearray(524288);rom[:8]=struct.pack('>II',0x200,0x06100000);rom[0x200:0x200+len(code)]=code
    lines=['# Original MIT timed controller synthetic BIOS. Adjacent LICENSE.', '# Generated by build_controller.py; unspecified bytes zero.']
    for at in range(0,len(rom),16):
        chunk=rom[at:at+16]
        if any(chunk): lines.append(f'{at:04X} '+' '.join(f'{w:04X}' for w in struct.unpack('>8H',chunk)))
    return source,'\n'.join(lines)+'\n',hashlib.sha256(rom).hexdigest()
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args()
    source,text,digest=build()
    for path,value in [(HERE/'controller.s',source),(HERE/'controller.hex',text)]:
        if a.check: assert path.read_text()==value,f'Rebuild {path.name}'
        else: path.write_text(value)
    print(f'{"Verified" if a.check else "Built"} controller.hex; expanded ROM SHA-256 {digest}')
